      "cover_image_url": null,
      "published": true,
      "published_at": "2026-11-04T00:43:00.000Z",
      "created_by": null,
      "author_id": "6a308470-2d8d-4cd8-996b-a96de32efdc2",
      "created_at": "2026-11-04T00:43:00.000Z",
